# Writes the Sagehen calibration's SUMMA TOML configuration; sourced by test_calibration_sagehen.sh and hpc/fir.
#   write_sagehen_config <config.toml> <work dir> <observations dir> <mizuRoute settings dir> <n_samples> <population>
# The work dir holds domain/ (from build_sagehen9_calibration.py), state/ and output/.
write_sagehen_config() {
  local out=$1 work=$2 obs=$3 mizu=$4 n_samples=$5 population=$6
  cat > "${out}" <<EOF
# generated by write_sagehen_config (sagehen_config.bash)

[simulation]

case_name = "sagehen"

# one spinup year (water year 2017) precedes the simulation, which the calibration then scores
start_time = "2017-10-01 01:00"
end_time   = "2018-09-30 23:00"
time_zone  = "utcTime"

use_mizuroute    = true
use_modflow      = true
write_timeseries = false

work_path = "${work}/output"


[summa_files]

settings_path = "${work}/domain/settings/SUMMA/"
forcing_path  = "${work}/domain/forcing/"
state_path    = "${work}/state/"
output_path   = "${work}/output/"

init_condition = "coldState.nc"
attributes     = "attributes.nc"
forcing_list   = "forcingFileList.txt"

decisions        = "modelDecisions.txt"
output_control   = "outputControl.txt"
trial_params     = "trialParams.nc"
local_parameters = "localParamInfo.txt"
basin_parameters = "basinParamInfo.txt"

vegetation_table = "TBL_VEGPARM.TBL"
soil_table       = "TBL_SOILPARM.TBL"
general_table    = "TBL_GENPARM.TBL"
noahmp_table     = "TBL_MPTABLE.TBL"


[modflow]

config_file = "${work}/domain/summa_modflow6.config"
run_dir     = "${work}/domain/mf6"


[mizuRoute]

namelist_path = "${mizu}/"
namelist_file = "mizuroute.param"

methods = "3"
dt      = 3600

write_qbasin = false
write_Qreach = false


[hydrofabric]

hfabric_path = "${work}/domain/"
hfabric_file = "topology.nc"

dname_seg = "seg"
dname_hru = "hru"

varname_HRUid     = "hruId"
varname_segId     = "segId"
varname_hruSegId  = "hruToSegId"
varname_downSegId = "downSegId"

varname_area   = "area"
varname_slope  = "slope"
varname_length = "length"


[calibration]

algorithm = "nsga2"

start_date = "2017-10-01"
end_date   = "2018-09-30"

n_samples = ${n_samples}

param_list = [
    "k_soil",
    "theta_sat",
    "qSurfScale",
    "summerLAI",
    "frozenPrecipMultip",
    "Fcapil",
    "tempCritRain",
    "heightCanopyTop",
    "heightCanopyBottom",
    "windReductionParam",
    "vGn_n",
    "routingGammaScale",
    "routingGammaShape"
]

write_aligned = false


[calibration.parameter_transformations]

k_soil            = "log"
routingGammaScale = "log"
K_mult            = "log"


[[parameter_dependencies.ordered]]

parameters   = ["heightCanopyBottom", "heightCanopyTop"]
gap_fraction = 0.25

[[parameter_dependencies.ordered]]

parameters   = ["theta_res", "critSoilWilting", "critSoilTranspire", "fieldCapacity", "theta_sat"]
gap_fraction = 0.025
sample_gaps  = true


# MODFLOW parameters: multipliers on the input files of [modflow] run_dir, rewritten for each trial;
# a zone_file and zone limit one to a zone, e.g. zone_file = "kzone1.txt", zone = 4
[[calibration.modflow_parameter]]

name  = "K_mult"
files = ["kh1.txt", "kv1.txt"]
lower = 0.2
upper = 5.0

[[calibration.modflow_parameter]]

name  = "Sy_mult"
files = "sy1.txt"
lower = 0.5
upper = 1.5
[calibration.nsga2]

population_size = ${population}


# discharge at the gauge, the outlet of reach 9
[[calibration.target]]

name      = "discharge"
variable  = "streamflow"
reach     = 9
obs_path  = "${obs}/"
obs_file  = "USGS_10343500_daily_flow.nc"
vname_obs = "q_obs"
metric    = "kge"


# water temperature leaving reach 9
[[calibration.target]]

name      = "stream_temperature"
variable  = "T_reach"
reach     = 9
obs_path  = "${obs}/"
obs_file  = "USGS_10343500_daily_temperature.nc"
vname_obs = "t_obs"
metric    = "rmse"


# water level in the synthetic well, the head at its cell (sagehen.obs), as departures from the
# water-year means, since its datum is not the model's
[[calibration.target]]

name           = "well_level"
variable       = "modflow_obs"
obs_name       = "well1"
obs_path       = "${obs}/"
obs_file       = "SYNTHETIC-SAGEHEN-1_daily_level.nc"
vname_obs      = "h_obs"
metric         = "rmse"
baseline_start = "2017-10-01"
baseline_end   = "2018-09-30"
EOF
}
